43.solution:
struct Node<T> {
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}

struct Bst<T> { root: Option<Box<Node<T>>>, len: usize }

impl<T: Ord> Bst<T> {
    fn new() -> Self { Self { root: None, len: 0 } }

    fn insert(&mut self, value: T) -> bool {
        let inserted = Self::insert_node(&mut self.root, value);
        if inserted { self.len += 1; }
        inserted
    }

    fn insert_node(node: &mut Option<Box<Node<T>>>, value: T) -> bool {  // recurses through &mut Option>>, not by returning a new tree
        match node {
            None => { *node = Some(Box::new(Node { value, left: None, right: None })); true }
            Some(n) => match value.cmp(&n.value) {
                std::cmp::Ordering::Less    => Self::insert_node(&mut n.left, value),
                std::cmp::Ordering::Greater => Self::insert_node(&mut n.right, value),
                std::cmp::Ordering::Equal   => false,  // already present — no duplicates, no accidental double-count
            },
        }
    }

    fn contains(&self, value: &T) -> bool {
        let mut cur = &self.root;
        while let Some(n) = cur {
            match value.cmp(&n.value) {
                std::cmp::Ordering::Less    => cur = &n.left,
                std::cmp::Ordering::Greater => cur = &n.right,
                std::cmp::Ordering::Equal   => return true,
            }
        }
        false
    }

    fn len(&self) -> usize { self.len }

    fn iter(&self) -> InOrderIter<'_, T> {
        let mut stack = Vec::new();  // push every left-spine ancestor down to the smallest value first
        let mut cur = self.root.as_deref();
        while let Some(n) = cur { stack.push(n); cur = n.left.as_deref(); }
        InOrderIter { stack }
    }
}

struct InOrderIter<'a, T> { stack: Vec<&'a Node<T>> }

impl<'a, T> Iterator for InOrderIter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.stack.pop()?;  // top of stack = next-smallest unvisited value — classic Morris-free in-order walk
        let mut cur = node.right.as_deref();
        while let Some(n) = cur { self.stack.push(n); cur = n.left.as_deref(); }
        Some(&node.value)
    }
}

impl<'a, T: Ord> IntoIterator for &'a Bst<T> {
    type Item = &'a T;
    type IntoIter = InOrderIter<'a, T>;
    fn into_iter(self) -> Self::IntoIter { self.iter() }
}

fn main() {
    let mut tree: Bst<i32> = Bst::new();
    for v in [5, 3, 8, 1, 4, 7, 9, 3] { tree.insert(v); }

    assert_eq!(tree.len(), 7);  // the second `3` was correctly rejected, not double-counted
    assert!(tree.contains(&7));

    let sorted: Vec<i32> = tree.iter().copied().collect();
    assert_eq!(sorted, vec![1, 3, 4, 5, 7, 8, 9]);

    let via_for: Vec<i32> = (&tree).into_iter().copied().collect();  // exercises `for x in &tree` directly
    assert_eq!(via_for, sorted);
}

