use std::cell::RefCell;
use std::collections::HashMap;
use std::hash::Hash;
use std::rc::Rc;

struct Memoizer<K, V, F> { cache: RefCell<HashMap<K, V>>, compute: F }

impl<K, V, F> Memoizer<K, V, F>
where
    K: Eq + Hash + Clone,
    V: Clone,
    F: Fn(K) -> V,
{
    fn new(compute: F) -> Self { Self { cache: RefCell::new(HashMap::new()), compute } }

    fn call(&self, key: K) -> V {
        if let Some(hit) = self.cache.borrow().get(&key) { return hit.clone(); }  // interior mutability — cache lives behind &self, not &mut self
        let value = (self.compute)(key.clone());
        self.cache.borrow_mut().insert(key, value.clone());
        value
    }

    fn cache_len(&self) -> usize { self.cache.borrow().len() }
}

// Self-recursive memoization (fibonacci needs to call ITSELF through the cache) can't be
// expressed via Memoizer as written: F: Fn(K) -> V has no way to reach back into
// the cache that contains it, and giving F a `&Memoizer` parameter makes the struct's
// own type reference itself — rustc rejects this outright (E0644: cyclic type of infinite
// size). Real recursive-memoized code ties the knot manually with Rc instead:
struct Fib { cache: RefCell<HashMap<u64, u64>> }

impl Fib {
    fn new() -> Rc<Self> { Rc::new(Self { cache: RefCell::new(HashMap::new()) }) }

    fn call(self: &Rc<Self>, n: u64) -> u64 {  // Rc receiver — the recursive call below can clone/reuse it freely
        if n <= 1 { return n; }
        if let Some(&hit) = self.cache.borrow().get(&n) { return hit; }
        let value = self.call(n - 1) + self.call(n - 2);
        self.cache.borrow_mut().insert(n, value);
        value
    }
}

// ── Part 2: bottom-up DP tables, no memoizer — a deliberate style contrast ──

fn knapsack(weights: &[u32], values: &[u32], capacity: u32) -> u32 {
    let (n, cap) = (weights.len(), capacity as usize);
    let mut table = vec![vec![0u32; cap + 1]; n + 1];  // table[i][c] = best value using first i items within capacity c

    for i in 1..=n {
        let (w, v) = (weights[i - 1] as usize, values[i - 1]);
        for c in 0..=cap {
            table[i][c] = if w > c { table[i - 1][c] } else { table[i - 1][c].max(table[i - 1][c - w] + v) };
        }
    }
    table[n][cap]
}

fn lcs(a: &[u8], b: &[u8]) -> (usize, Vec<u8>) {
    let (n, m) = (a.len(), b.len());
    let mut table = vec![vec![0usize; m + 1]; n + 1];

    for i in 1..=n {
        for j in 1..=m {
            table[i][j] = if a[i-1] == b[j-1] { table[i-1][j-1] + 1 } else { table[i-1][j].max(table[i][j-1]) };
        }
    }

    let mut seq = Vec::with_capacity(table[n][m]);  // backtrack from the bottom-right corner to recover the actual subsequence
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
        if a[i-1] == b[j-1] { seq.push(a[i-1]); i -= 1; j -= 1; }
        else if table[i-1][j] >= table[i][j-1] { i -= 1; }
        else { j -= 1; }
    }
    seq.reverse();
    (table[n][m], seq)
}

fn coin_change(coins: &[u32], amount: u32) -> Option<u32> {
    let amt = amount as usize;
    let mut dp = vec![u32::MAX; amt + 1];  // u32::MAX doubles as "unreachable" — no Option needed inside the table itself
    dp[0] = 0;

    for c in 0..=amt {
        if dp[c] == u32::MAX { continue; }
        for &coin in coins {
            let next = c + coin as usize;
            if next <= amt { dp[next] = dp[next].min(dp[c] + 1); }
        }
    }
    (dp[amt] != u32::MAX).then_some(dp[amt])  // bool::then_some — clean bridge from a sentinel value back to Option
}

fn main() {
    let slow_square = Memoizer::new(|n: u64| n * n);
    assert_eq!(slow_square.call(7), 49);
    assert_eq!(slow_square.call(7), 49);  // second call is a cache hit — .compute is never invoked again for key 7
    assert_eq!(slow_square.cache_len(), 1);

    let fib = Fib::new();
    assert_eq!(fib.call(30), 832_040);

    assert_eq!(knapsack(&[2,3,4,5], &[3,4,5,6], 5), 7);

    let (len, seq) = lcs(b"ABCBDAB", b"BDCABA");
    assert_eq!(len, 4);
    assert_eq!(String::from_utf8(seq).unwrap(), "BCBA");

    assert_eq!(coin_change(&[1,5,6,8], 11), Some(2));  // 5 + 6
    assert_eq!(coin_change(&[5,7], 3), None);
}

