use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn merge_intervals(mut intervals: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    if intervals.is_empty() { return Vec::new(); }
    intervals.sort_unstable_by_key(|&(start, _)| start);  // sort by START — that's the order we sweep in

    let mut merged = Vec::with_capacity(intervals.len());
    let mut current = intervals[0];

    for &(start, end) in &intervals[1..] {
        if start <= current.1 { current.1 = current.1.max(end); }  // overlap OR touch — extend, never shrink the running end
        else { merged.push(current); current = (start, end); }
    }
    merged.push(current);
    merged
}

fn min_meeting_rooms(mut meetings: Vec<(i64, i64)>) -> usize {
    if meetings.is_empty() { return 0; }
    meetings.sort_unstable_by_key(|&(start, _)| start);  // also sort by START — we're asking "in this arrival order, do we need a new room?"

    let mut room_end_times: BinaryHeap<Reverse<i64>> = BinaryHeap::new();  // min-heap of end times — peek always sees the SOONEST-freeing room
    let mut rooms_used = 0;

    for (start, end) in meetings {
        if let Some(&Reverse(earliest_free)) = room_end_times.peek() {
            if earliest_free <= start { room_end_times.pop(); }  // reuse the room that's already free by the time this meeting starts
            else { rooms_used += 1; }
        } else { rooms_used += 1; }
        room_end_times.push(Reverse(end));
    }
    rooms_used
}

fn max_non_overlapping(mut intervals: Vec<(i64, i64)>) -> usize {
    intervals.sort_unstable_by_key(|&(_, end)| end);  // sort by END, not start — the greedy proof requires this key specifically

    let mut count = 0;
    let mut last_end = i64::MIN;
    for (start, end) in intervals {
        if start >= last_end { count += 1; last_end = end; }
    }
    count
}

fn main() {
    assert_eq!(merge_intervals(vec![(1,3),(2,6),(8,10),(15,18)]), vec![(1,6),(8,10),(15,18)]);
    assert_eq!(merge_intervals(vec![(1,4),(4,5)]), vec![(1,5)]);  // touching endpoints DO merge

    assert_eq!(min_meeting_rooms(vec![(0,30),(5,10),(15,20)]), 2);
    assert_eq!(min_meeting_rooms(vec![(7,10),(2,4)]), 1);

    assert_eq!(max_non_overlapping(vec![(1,3),(2,4),(3,5),(0,6)]), 2);  // keep (1,3) and (3,5); (0,6) alone would only give 1
}

