use std::collections::{BinaryHeap, HashMap, VecDeque};

// Greedy idea, made concrete: a max-heap of remaining counts (BinaryHeap needs NO Reverse
// here — we WANT the biggest remaining count to pop first) plus a cooldown queue holding
// tasks that just ran, each tagged with the tick they become eligible again.
fn least_interval(tasks: &[char], n: u32) -> u32 {
    let mut counts: HashMap<char, u32> = HashMap::new();
    for &t in tasks { *counts.entry(t).or_insert(0) += 1; }

    let mut heap: BinaryHeap<u32> = counts.values().copied().collect();
    let mut cooling: VecDeque<(u32, u32)> = VecDeque::new();  // (remaining_count, ready_at_tick) — FIFO since cooldowns expire in the order they started
    let mut time = 0u32;

    while !heap.is_empty() || !cooling.is_empty() {
        time += 1;
        if let Some(count) = heap.pop() {  // run the most-frequent remaining task this tick
            if count > 1 { cooling.push_back((count - 1, time + n)); }  // still has runs left — parks in cooldown, not back in the heap yet
        }
        if let Some(&(_, ready_at)) = cooling.front() {  // exactly ONE task can become eligible per tick under this scheme
            if ready_at == time {
                let (remaining, _) = cooling.pop_front().unwrap();
                heap.push(remaining);
            }
        }
        // heap empty AND cooling non-empty on this tick means EVERY remaining task is still on cooldown —
        // that tick is silently a forced idle slot, already counted since `time` was incremented above
    }
    time
}

fn build_schedule(tasks: &[char], n: u32) -> Vec<Option<char>> {
    let mut counts: HashMap<char, u32> = HashMap::new();
    for &t in tasks { *counts.entry(t).or_insert(0) += 1; }

    let mut heap: BinaryHeap<(u32, std::cmp::Reverse<char>)> =  // tie-break by char so output is deterministic across runs
        counts.iter().map(|(&c, &n)| (n, std::cmp::Reverse(c))).collect();
    let mut cooling: VecDeque<(u32, char, u32)> = VecDeque::new();
    let mut schedule = Vec::new();
    let mut time = 0u32;

    while !heap.is_empty() || !cooling.is_empty() {
        time += 1;
        if let Some((count, std::cmp::Reverse(ch))) = heap.pop() {
            schedule.push(Some(ch));
            if count > 1 { cooling.push_back((count - 1, ch, time + n)); }
        } else { schedule.push(None); }  // heap empty — forced idle, recorded explicitly this time
        if let Some(&(_, _, ready_at)) = cooling.front() {
            if ready_at == time {
                let (remaining, ch, _) = cooling.pop_front().unwrap();
                heap.push((remaining, std::cmp::Reverse(ch)));
            }
        }
    }
    schedule
}

fn main() {
    let tasks: Vec<char> = "AAABBB".chars().collect();
    assert_eq!(least_interval(&tasks, 2), 8);  // A B _ A B _ A B — one forced idle per 3-tick cycle since two tasks tie at max count

    let schedule = build_schedule(&tasks, 2);
    assert_eq!(schedule.len(), 8);

    assert_eq!(least_interval(&tasks, 0), 6);  // no cooldown -> just run everything back to back

    let heavy: Vec<char> = "AAAA".chars().collect();
    assert_eq!(least_interval(&heavy, 2), 10);  // A..A..A..A — no OTHER task exists to fill the forced idle gaps
}

