use std::fmt;
use std::ops::{Add, Index, IndexMut, Mul};

#[derive(Clone, PartialEq)]
struct Matrix<T> { rows: usize, cols: usize, data: Vec<T> }

impl<T: Copy + Default> Matrix<T> {
    fn zeros(rows: usize, cols: usize) -> Self {
        Self { rows, cols, data: vec![T::default(); rows * cols] }  // Copy required here — vec![x; n] copies x, doesn't clone-construct n times
    }

    fn from_rows(rows_data: Vec<Vec<T>>) -> Self {
        let rows = rows_data.len();
        let cols = rows_data.first().map_or(0, |r| r.len());
        assert!(rows_data.iter().all(|r| r.len() == cols), "ragged matrix rows");  // defend the "rectangular" invariant up front
        Self { rows, cols, data: rows_data.into_iter().flatten().collect() }
    }

    fn row(&self, r: usize) -> &[T] { &self.data[r * self.cols..(r + 1) * self.cols] }

    fn rows_iter(&self) -> impl Iterator<Item = &[T]> {  // impl Trait return — caller gets "some iterator," concrete type is compiler's business
        (0..self.rows).map(move |r| self.row(r))
    }

    fn transpose(&self) -> Self {
        let mut out = Matrix::zeros(self.cols, self.rows);
        for r in 0..self.rows {
            for c in 0..self.cols { out[(c, r)] = self[(r, c)]; }
        }
        out
    }
}

impl<T> Index<(usize, usize)> for Matrix<T> {
    type Output = T;
    fn index(&self, (r, c): (usize, usize)) -> &T {  // no T: Copy/Default needed just to INDEX — only construction needs those bounds
        assert!(r < self.rows && c < self.cols, "index out of bounds");
        &self.data[r * self.cols + c]
    }
}
impl<T> IndexMut<(usize, usize)> for Matrix<T> {
    fn index_mut(&mut self, (r, c): (usize, usize)) -> &mut T {
        assert!(r < self.rows && c < self.cols, "index out of bounds");
        &mut self.data[r * self.cols + c]
    }
}

impl<T: Copy + Default + Add<Output = T>> Add for Matrix<T> {
    type Output = Matrix<T>;
    fn add(self, rhs: Matrix<T>) -> Matrix<T> {
        assert_eq!((self.rows, self.cols), (rhs.rows, rhs.cols), "shape mismatch");
        let data = self.data.iter().zip(rhs.data.iter()).map(|(&a, &b)| a + b).collect();  // zip + map — no manual index loop needed
        Matrix { rows: self.rows, cols: self.cols, data }
    }
}

// Matrix multiply borrows both operands (&Matrix, not Matrix by value) — unlike Add, you
// almost always want to reuse both matrices again after multiplying, and there's no reason
// to force a move/consume for a read-only operation.
impl<T: Copy + Default + Add<Output = T> + Mul<Output = T>> Mul for &Matrix<T> {
    type Output = Matrix<T>;
    fn mul(self, rhs: &Matrix<T>) -> Matrix<T> {
        assert_eq!(self.cols, rhs.rows, "inner dimensions must match");  // (m×n) * (n×p) — inner dims n must agree
        let mut out = Matrix::zeros(self.rows, rhs.cols);
        for r in 0..self.rows {
            for c in 0..rhs.cols {
                let mut acc = T::default();
                for k in 0..self.cols { acc = acc + self[(r, k)] * rhs[(k, c)]; }
                out[(r, c)] = acc;
            }
        }
        out
    }
}

impl<T: fmt::Debug> fmt::Debug for Matrix<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for r in 0..self.rows { writeln!(f, "{:?}", &self.data[r * self.cols..(r + 1) * self.cols])?; }
        Ok(())
    }
}

fn main() {
    let a = Matrix::from_rows(vec![vec![1,2], vec![3,4]]);
    let b = Matrix::from_rows(vec![vec![5,6], vec![7,8]]);

    let sum = a.clone() + b.clone();
    assert_eq!(sum.data, vec![6,8,10,12]);

    let product = &a * &b;
    assert_eq!(product.data, vec![19,22,43,50]);  // [1,2;3,4] × [5,6;7,8] = [19,22;43,50]

    assert_eq!(a.transpose().data, vec![1,3,2,4]);

    let row_sums: Vec<i32> = a.rows_iter().map(|row| row.iter().sum()).collect();
    assert_eq!(row_sums, vec![3, 7]);
}

