use std::collections::{BTreeMap, HashMap, VecDeque};
use std::error::Error;
use std::fmt;

#[derive(Debug)]
enum StoreError { NotFound(String) }

impl fmt::Display for StoreError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self { StoreError::NotFound(key) => write!(f, "key not found: {key}") }
    }
}
impl Error for StoreError {}  // blanket Display + Debug is all Error needs by default — no methods to implement

// A deliberately simple LRU: HashMap for O(1) lookup, VecDeque tracking recency by key.
// touch()/remove() are O(n) here (linear scan of the recency queue) — an intentional,
// named trade-off versus the O(1) intrusive-doubly-linked-list + HashMap>
// design a production cache (and W8's LRU exercise) would use instead.
struct LruCache<V> { capacity: usize, map: HashMap<String, V>, recency: VecDeque<String> }

impl<V: Clone> LruCache<V> {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "cache capacity must be > 0");
        Self { capacity, map: HashMap::new(), recency: VecDeque::new() }
    }

    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.recency.iter().position(|k| k == key) {
            let k = self.recency.remove(pos).unwrap();
            self.recency.push_back(k);  // move to the back = "most recently used"
        }
    }

    fn get(&mut self, key: &str) -> Option<V> {
        let value = self.map.get(key).cloned()?;
        self.touch(key);
        Some(value)
    }

    fn put(&mut self, key: String, value: V) {
        if self.map.contains_key(&key) {
            self.map.insert(key.clone(), value);
            self.touch(&key);
            return;
        }
        if self.map.len() >= self.capacity {
            if let Some(oldest) = self.recency.pop_front() { self.map.remove(&oldest); }  // evict the LEAST recently used — the front of the queue
        }
        self.recency.push_back(key.clone());
        self.map.insert(key, value);
    }

    fn remove(&mut self, key: &str) {
        self.map.remove(key);
        if let Some(pos) = self.recency.iter().position(|k| k == key) { self.recency.remove(pos); }
    }
}

// The storage abstraction — anything implementing this trait can back the document store:
// the BTreeMap-backed implementation below, an in-memory test double, or (in a real system)
// a disk-backed engine, all behind the exact same interface.
trait Storage<V: Clone> {
    fn get(&mut self, key: &str) -> Result<V, StoreError>;
    fn put(&mut self, key: String, value: V);
    fn delete(&mut self, key: &str) -> Option<V>;
    fn range(&self, start: &str, end: &str) -> Vec<(String, V)>;
}

struct DocumentStore<V> {
    backing: BTreeMap<String, V>,  // sorted storage — the ONLY reason .range() is possible at all
    cache: LruCache<V>,
}

impl<V: Clone> DocumentStore<V> {
    fn new(cache_capacity: usize) -> Self {
        Self { backing: BTreeMap::new(), cache: LruCache::new(cache_capacity) }
    }

    // Generic query engine: any predicate closure over &V, expressed purely via iterator
    // adapters (filter + map + collect) — no manual loop, no allocation beyond the final Vec.
    fn query<F>(&self, predicate: F) -> Vec<(String, V)>
    where F: Fn(&V) -> bool,
    {
        self.backing.iter().filter(|(_, v)| predicate(v)).map(|(k, v)| (k.clone(), v.clone())).collect()
    }

    fn count_where<F>(&self, predicate: F) -> usize where F: Fn(&V) -> bool {
        self.backing.values().filter(|v| predicate(v)).count()
    }
}

impl<V: Clone> Storage<V> for DocumentStore<V> {
    fn get(&mut self, key: &str) -> Result<V, StoreError> {
        if let Some(hit) = self.cache.get(key) { return Ok(hit); }  // cache hit — never touches the BTreeMap at all
        let value = self.backing.get(key).cloned().ok_or_else(|| StoreError::NotFound(key.to_string()))?;
        self.cache.put(key.to_string(), value.clone());
        Ok(value)
    }

    fn put(&mut self, key: String, value: V) {
        self.backing.insert(key.clone(), value.clone());
        self.cache.put(key, value);  // write-through — cache and backing store updated together, never diverge
    }

    fn delete(&mut self, key: &str) -> Option<V> {
        self.cache.remove(key);
        self.backing.remove(key)
    }

    fn range(&self, start: &str, end: &str) -> Vec<(String, V)> {
        self.backing.range(start.to_string()..end.to_string()).map(|(k, v)| (k.clone(), v.clone())).collect()  // end bound EXCLUSIVE, matching Rust's Range semantics
    }
}

#[derive(Clone, Debug, PartialEq)]
struct User { name: String, age: u32, active: bool }

fn main() -> Result<(), Box<dyn Error>> {
    let mut store: DocumentStore<User> = DocumentStore::new(2);  // tiny cache on purpose — forces a real eviction below

    store.put("user:001".into(), User { name: "Ada".into(), age: 34, active: true });
    store.put("user:002".into(), User { name: "Grace".into(), age: 45, active: false });
    store.put("user:003".into(), User { name: "Linus".into(), age: 29, active: true });

    assert_eq!(store.get("user:001")?.name, "Ada");
    assert_eq!(store.get("user:002")?.name, "Grace");
    assert_eq!(store.get("user:003")?.name, "Linus");  // cache capacity 2 -> this evicts "user:001" from the CACHE only, not the backing store
    assert_eq!(store.get("user:001")?.name, "Ada");  // still correct — falls through to the BTreeMap on cache miss, exactly as designed

    match store.get("user:999") {
        Err(StoreError::NotFound(key)) => assert_eq!(key, "user:999"),
        _ => panic!("expected NotFound"),
    }

    let active_over_30 = store.query(|u| u.active && u.age > 30);  // closure as a first-class predicate — no query-language string parsing anywhere
    assert_eq!(active_over_30.len(), 1);
    assert_eq!(active_over_30[0].1.name, "Ada");

    assert_eq!(store.count_where(|u| u.active), 2);

    let range = store.range("user:001", "user:003");  // only possible because the backing store is a BTreeMap, sorted by key
    assert_eq!(range.len(), 2);  // "user:001" and "user:002" — end bound exclusive

    let total_age: u32 = store.query(|_| true).iter().fold(0, |acc, (_, u)| acc + u.age);  // fold — combining iterators + closures + generics in one line
    assert_eq!(total_age, 34 + 45 + 29);

    let deleted = store.delete("user:002");
    assert_eq!(deleted.map(|u| u.name), Some("Grace".to_string()));
    assert!(store.get("user:002").is_err());

    Ok(())
}

