use std::mem::MaybeUninit;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

struct RingBuffer<T> {
    buf: *mut T,    // raw pointer to `capacity` contiguous, initially-uninitialized elements
    capacity: usize,
    head: AtomicUsize,
    tail: AtomicUsize,
}

// SAFETY: access to `buf` is disciplined entirely through the head/tail atomics — the
// producer only ever writes to slots the consumer has already vacated (checked via
// Acquire-loaded `head`), and the consumer only ever reads slots the producer has already
// published (checked via Acquire-loaded `tail`). No two threads ever touch the same slot
// concurrently, so sharing the raw pointer across threads is sound.
unsafe impl<T: Send> Send for RingBuffer<T> {}
unsafe impl<T: Send> Sync for RingBuffer<T> {}

pub struct Producer<T> { ring: Arc<RingBuffer<T>> }
pub struct Consumer<T> { ring: Arc<RingBuffer<T>> }

pub fn channel<T>(capacity: usize) -> (Producer<T>, Consumer<T>) {
    assert!(capacity.is_power_of_two(), "capacity must be a power of two for the mask trick");

    let boxed: Box<[MaybeUninit<T>]> = (0..capacity).map(|_| MaybeUninit::uninit()).collect();
    // Box::into_raw gives back a FAT pointer (data + length); casting to *mut T drops the length
    // metadata since we track `capacity` ourselves — MaybeUninit and T share layout, so pointer
    // arithmetic in units of T lines up exactly with the original allocation.
    let buf = Box::into_raw(boxed) as *mut T;

    let ring = Arc::new(RingBuffer { buf, capacity, head: AtomicUsize::new(0), tail: AtomicUsize::new(0) });
    (Producer { ring: ring.clone() }, Consumer { ring })
}

impl<T> Producer<T> {
    pub fn push(&self, value: T) -> Result<(), T> {
        let ring = &*self.ring;
        let tail = ring.tail.load(Ordering::Relaxed);   // only the producer ever writes tail — Relaxed is safe here
        let head = ring.head.load(Ordering::Acquire);   // must see the consumer's latest progress before checking "full"

        if tail.wrapping_sub(head) >= ring.capacity {
            return Err(value);
        }

        let idx = tail & (ring.capacity - 1);
        unsafe { std::ptr::write(ring.buf.add(idx), value) };  // moves `value` in without ever forming a &mut to the (garbage) old contents
        ring.tail.store(tail.wrapping_add(1), Ordering::Release);  // publishes the write above — consumer's Acquire load of tail is now guaranteed to see it
        Ok(())
    }
}

impl<T> Consumer<T> {
    pub fn pop(&self) -> Option<T> {
        let ring = &*self.ring;
        let head = ring.head.load(Ordering::Relaxed);   // only the consumer ever writes head
        let tail = ring.tail.load(Ordering::Acquire);   // must see the producer's published write

        if head == tail { return None; }

        let idx = head & (ring.capacity - 1);
        let value = unsafe { std::ptr::read(ring.buf.add(idx)) };  // moves the value OUT, leaving the slot logically uninitialized again
        ring.head.store(head.wrapping_add(1), Ordering::Release);
        Some(value)
    }
}

impl<T> Drop for RingBuffer<T> {
    fn drop(&mut self) {
        // slots between head..tail were written but never popped (e.g. the channel was dropped
        // mid-flight) — a raw allocation does NOT drop its contents automatically, so skipping
        // this would silently leak every unconsumed element.
        let head = *self.head.get_mut();
        let tail = *self.tail.get_mut();
        let mut idx = head;
        while idx != tail {
            let slot = idx & (self.capacity - 1);
            unsafe { std::ptr::drop_in_place(self.buf.add(slot)) };
            idx = idx.wrapping_add(1);
        }
        unsafe {  // reconstruct the original boxed slice so Box's own Drop frees the memory with the exact layout it was allocated with
            let slice_ptr = std::ptr::slice_from_raw_parts_mut(self.buf as *mut MaybeUninit<T>, self.capacity);
            drop(Box::from_raw(slice_ptr));
        }
    }
}

fn main() {
    const N: usize = 10_000;
    let (producer, consumer) = channel::<u64>(1024);

    let producer_thread = std::thread::spawn(move || {
        for i in 0..N as u64 {
            loop {
                match producer.push(i) {
                    Ok(()) => break,
                    Err(_full) => std::hint::spin_loop(),  // buffer full — spin rather than block, the whole point of "low latency"
                }
            }
        }
    });

    let consumer_thread = std::thread::spawn(move || {
        let mut sum = 0u64;
        let mut received = 0usize;
        while received < N {
            match consumer.pop() {
                Some(v) => { sum += v; received += 1; }
                None => std::hint::spin_loop(),
            }
        }
        sum
    });

    producer_thread.join().unwrap();
    let sum = consumer_thread.join().unwrap();

    assert_eq!(sum, (0..N as u64).sum());

    let (p2, c2) = channel::<String>(4);  // dropped mid-flight with unconsumed elements — must not leak
    p2.push("a".to_string()).unwrap();
    p2.push("b".to_string()).unwrap();
    drop(p2);
    drop(c2);
}

